(1950756, 268943, 45790, '<td valign="top">Darn! Made me laugh. Good idea, but lighting is a real problem here as the subject, the cheese, has major overexposure. If it were a little more even, so as to still keep the background dark but more even exposure on the cheese, this would have been a winner for me.</td>', 'Darn! Made me laugh. Good idea, but lighting is a real problem here as the subject, the cheese, has major overexposure. If it were a little more even, so as to still keep the background dark but more even exposure on the cheese, this would have been a winner for me.', '2005-12-14 11:42:07.000000', NULL, 1),
(1950759, 268436, 6519, '<td valign="top">This is not my pick of the bunch for this particular challenge, but WOW - what an awesome portrait!!!!!  Stunning photo!!!</td>', 'This is not my pick of the bunch for this particular challenge, but WOW - what an awesome portrait!!!!!  Stunning photo!!!', '2005-12-14 11:42:50.000000', NULL, 1),
