(1965222, 268653, 15711, '<td valign="top">That is a beautiful kitty. Love the hairy ears. hee hee Would be great if he''d be looking at the cheese, but then you''re lucky that he sat there - trust me, I know cats. ROFL</td>', 'That is a beautiful kitty. Love the hairy ears. hee hee Would be great if he''d be looking at the cheese, but then you''re lucky that he sat there - trust me, I know cats. ROFL', '2005-12-20 15:06:28.000000', NULL, 1),
(1965224, 268851, 15711, '<td valign="top">Oh what a great title.  YUM - I love gouda.  This is really well done.</td>', 'Oh what a great title.  YUM - I love gouda.  This is really well done.', '2005-12-20 15:07:36.000000', NULL, 1),
