INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1966438, 268977, 40019, '<td valign="top">Outstanding!  You are SUCH a roll!! Congrats on the 4th place finish!</td>', 'Outstanding!  You are SUCH a roll!! Congrats on the 4th place finish!', '2005-12-21 00:43:46.000000', NULL, 0),
(1966440, 266653, 22734, '<td valign="top">Oh Rose! This image is missing only a ribbon. I think you did an outstanding job here. It is indeed a beauty and one that I would try to market to the cheese industry. <br/> <br/>Regardless, Congratulations on your top 5th placing and yes, you should have placed above my cheesehenge which used the cheese to portray stone.<br/><br/><i>Message edited by author 2005-12-23 00:38:54.</i></td>', 'Oh Rose! This image is missing only a ribbon. I think you did an outstanding job here. It is indeed a beauty and one that I would try to market to the cheese industry.  Regardless, Congratulations on your top 5th placing and yes, you should have placed above my cheesehenge which used the cheese to portray stone.', '2005-12-21 00:43:55.000000', '2005-12-23 00:38:54.000000', 0),
(1966444, 266913, 1827, '<td valign="top">This was so much funnier than it got credit for.  I don''t think it''s great technically, but if I''d voted you''d have gotten points for humor.</td>', 'This was so much funnier than it got credit for.  I don''t think it''s great technically, but if I''d voted you''d have gotten points for humor.', '2005-12-21 00:44:04.000000', NULL, 0),
