(1966465, 266242, 40019, '<td valign="top">Great shot Pedro!  I gave it a 10 by the way.</td>', 'Great shot Pedro!  I gave it a 10 by the way.', '2005-12-21 00:45:52.000000', NULL, 0),
(1966473, 266955, 22734, '<td valign="top">Congratulations on your top ten placing. I ran through this idea and was convinced someone else would do it.</td>', 'Congratulations on your top ten placing. I ran through this idea and was convinced someone else would do it.', '2005-12-21 00:47:24.000000', NULL, 0),
